import React from 'react';
import { NavLink } from 'react-router-dom';
import { 
  Home, 
  Bot, 
  FolderOpen, 
  FileText, 
  Settings,
  Activity,
  ArrowUp
} from 'lucide-react';
import { useBot } from '../contexts/BotContext';

const Sidebar = () => {
  const { botStatus } = useBot();

  const getStatusColor = (status) => {
    switch (status) {
      case 'running':
        return 'bg-success-500';
      case 'paused':
        return 'bg-warning-500';
      case 'error':
        return 'bg-error-500';
      default:
        return 'bg-gray-500';
    }
  };

  const getStatusText = (status) => {
    switch (status) {
      case 'running':
        return 'กำลังทำงาน';
      case 'paused':
        return 'หยุดชั่วคราว';
      case 'error':
        return 'เกิดข้อผิดพลาด';
      default:
        return 'หยุดทำงาน';
    }
  };

  const navItems = [
    { path: '/', icon: Home, label: 'แดชบอร์ด' },
    { path: '/bot-control', icon: Bot, label: 'ควบคุมบอท' },
    { path: '/file-manager', icon: FolderOpen, label: 'จัดการไฟล์' },
    { path: '/logs', icon: FileText, label: 'บันทึกการทำงาน' },
    { path: '/settings', icon: Settings, label: 'การตั้งค่า' },
    { path: '/back-to-top-examples', icon: ArrowUp, label: 'ตัวอย่าง BackToTop' },
  ];

  return (
    <div className="w-64 bg-white shadow-lg border-r border-gray-200">
      {/* Header */}
      <div className="p-6 border-b border-gray-200">
        <div className="flex items-center space-x-3">
          <div className="w-10 h-10 bg-primary-600 rounded-lg flex items-center justify-center">
            <Bot className="w-6 h-6 text-white" />
          </div>
          <div>
            <h1 className="text-xl font-bold text-gray-900">ระบบบอท</h1>
            <p className="text-sm text-gray-500">อัตโนมัติ</p>
          </div>
        </div>
      </div>

      {/* Bot Status */}
      <div className="p-4 border-b border-gray-200">
        <div className="flex items-center justify-between">
          <span className="text-sm font-medium text-gray-700">สถานะบอท:</span>
          <div className="flex items-center space-x-2">
            <div className={`w-3 h-3 rounded-full ${getStatusColor(botStatus)}`}></div>
            <span className="text-sm text-gray-600">{getStatusText(botStatus)}</span>
          </div>
        </div>
      </div>

      {/* Navigation */}
      <nav className="p-4">
        <ul className="space-y-2">
          {navItems.map((item) => (
            <li key={item.path}>
              <NavLink
                to={item.path}
                className={({ isActive }) =>
                  `flex items-center space-x-3 px-3 py-2 rounded-lg transition-colors duration-200 ${
                    isActive
                      ? 'bg-primary-100 text-primary-700 border-r-2 border-primary-600'
                      : 'text-gray-700 hover:bg-gray-100'
                  }`
                }
              >
                <item.icon className="w-5 h-5" />
                <span className="font-medium">{item.label}</span>
              </NavLink>
            </li>
          ))}
        </ul>
      </nav>

      {/* Footer */}
      <div className="absolute bottom-0 w-64 p-4 border-t border-gray-200">
        <div className="flex items-center space-x-2 text-sm text-gray-500">
          <Activity className="w-4 h-4" />
          <span>ระบบบอทอัตโนมัติ v1.0</span>
        </div>
      </div>
    </div>
  );
};

export default Sidebar;
